const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '入射光线' },
      { kind: 'text', payload: '法线' },
      { kind: 'text', payload: '反射光线' },
      { kind: 'text', payload: '反射角' }
    ];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var s = Math.min(W / 500, H / 400);
    var ox = (W - 500 * s) / 2;
    var oy = (H - 400 * s) / 2;
    function X(x) { return ox + x * s; }
    function Y(y) { return oy + y * s; }
    var mirror = visualSdk.polyline([[X(90), Y(300)], [X(410), Y(300)]]);
    var normal = visualSdk.polyline([[X(250), Y(300)], [X(250), Y(80)]]);
    var incident = visualSdk.arrow(X(105), Y(115), X(250), Y(300), {});
    var reflected = visualSdk.arrow(X(250), Y(300), X(395), Y(115), {});
    var arcPts = [];
    var a0 = -Math.PI / 2;
    var a1 = -0.906;
    for (var i = 0; i <= 24; i++) {
      var t = a0 + (a1 - a0) * (i / 24);
      arcPts.push([X(250) + 54 * s * Math.cos(t), Y(300) + 54 * s * Math.sin(t)]);
    }
    var angle = visualSdk.polyline(arcPts);
    return {
      schemaVersion: 1,
      sceneId: 'reflection-figure',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: [
        { id: 'mirror', commands: mirror },
        { id: 'normal', commands: normal },
        { id: 'incident', commands: incident },
        { id: 'reflected', commands: reflected },
        { id: 'angle', commands: angle }
      ],
      root: {
        type: 'group',
        children: [
          { type: 'path', pathId: 'mirror', fill: 'none', stroke: { width: 3, color: '#26354a' } },
          { type: 'path', pathId: 'normal', fill: 'none', stroke: { width: 2, color: '#26354a' } },
          { type: 'path', pathId: 'incident', fill: '#26354a', stroke: { width: 2, color: '#26354a' } },
          { type: 'path', pathId: 'reflected', fill: '#26354a', stroke: { width: 2, color: '#26354a' } },
          { type: 'path', pathId: 'angle', fill: 'none', stroke: { width: 2, color: '#26354a' } },
          { type: 'label', contentId: 'c0', anchor: { x: X(145), y: Y(150) }, hAlign: 'center', vAlign: 'bottom', color: '#26354a' },
          { type: 'label', contentId: 'c1', anchor: { x: X(268), y: Y(100) }, hAlign: 'left', vAlign: 'bottom', color: '#26354a' },
          { type: 'label', contentId: 'c2', anchor: { x: X(355), y: Y(150) }, hAlign: 'center', vAlign: 'bottom', color: '#26354a' },
          { type: 'label', contentId: 'c3', anchor: { x: X(292), y: Y(235) }, hAlign: 'left', vAlign: 'middle', color: '#26354a' }
        ]
      }
    };
  }
};
